//! Idempotently inject the li7-only bits into the rendered helm chart.
//!
//! The chart under out/deploy/li7/helm is GENERATED by the mosaic render
//! (the `aria-ask` sidecar — the hand-written Alexa surface — is an app
//! concern, not a mosaic concern), so every fresh render drops it. Run this
//! after every render:
//!
//!     rustc -O deploy/li7/inject.rs -o /tmp/aria-inject
//!     /tmp/aria-inject <helm-dir> [image-tag]   # tag default: latest
//!
//! It (re)adds:
//!   * the `aria-ask` container (the ASK protocol + /stream + /art + the scanner)
//!   * the hostPath mounts the pod actually needs on li7:
//!       /home/ee/audio        -> /media   (the audio files; both containers)
//!       /var/lib/aria-data    -> /data    (knowledge base; both containers)
//!       /var/lib/aria-lancedb -> /vector  (embedded LanceDB; brain only)
//!   * the named service ports (api + ask)
//!   * the ingress path split (/alexa, /stream, /art -> ask; the rest -> api)
//!   * a no-surge rollout strategy (li7 is memory-tight — an old aria pod and
//!     its replacement may never be scheduled at the same time)
//!
//! Everything is baked into the template so ONE `helm upgrade` produces the
//! final pod spec — a post-helm `kubectl patch` would mutate the template a
//! second time, spawn a second ReplicaSet, and (with the no-surge strategy
//! still rolling the first) leave two pods reserving memory they cannot both
//! get. Skips cleanly when already present.
//!
//! Single file, std only: `rustc -O inject.rs` is the whole build.

use std::fs;
use std::path::Path;
use std::process::exit;

const SIDECAR: &str = r#"
        # li7-only sidecar (injected by deploy/li7/inject.rs — the
        # chart itself is render-generated): the ASK surface + the web app.
        # The ingress routes /alexa, /stream/*, /art/*, /skill-icons AND the
        # web app (/ → SPA, /dl → download API) here (port 8090); the brain
        # keeps /api, /mcp, /openapi.json, /readyz.
        - name: aria-ask
          image: mosaic/aria-ask:__TAG__
          imagePullPolicy: Never
          ports:
            - containerPort: 8090
          env:
            # The baked config (adapter/config/aria.example.toml) carries the
            # collection paths + scan output; the secrets ride the env.
            - name: ARIA_PUBLIC_URL
              value: "https://aria.eisler-systems.de"
            - name: ARIA_DATA_DIR
              value: /data/adapter
            - name: ARIA_BRAIN_URL
              value: "http://127.0.0.1:3000"
            - name: ARIA_BRAIN_TOKEN
              valueFrom:
                secretKeyRef:
                  # The brain's `adapter` service-account secret (the same
                  # value the app validates as MOAIC_ADAPTER_TOKEN).
                  name: moaic-adapter-token
                  key: MOAIC_ADAPTER_TOKEN
            # The Alexa skill client id (Endpoint configuration → Client ID)
            # rides the moaic-aria-client-id secret (created by the deploy
            # workflow from /home/ee/.ssh/aria-client-id, house pattern).
            # optional: missing secret = env absent = the check stays off
            # (fail-soft until the skill is registered).
            - name: ARIA_CLIENT_ID
              valueFrom:
                secretKeyRef:
                  name: moaic-aria-client-id
                  key: ARIA_CLIENT_ID
                  optional: true
            # Web-app login token for /dl/* (the download manager). Rides a
            # secret like the client id; optional = open access (dev).
            - name: ARIA_WEB_TOKEN
              valueFrom:
                secretKeyRef:
                  name: moaic-aria-web-token
                  key: ARIA_WEB_TOKEN
                  optional: true
            # The brain's JWT signing secret — the web login verifies the
            # brain's /api/auth/login tokens (HS256) locally, so one
            # credential system covers voice + web (same as bible).
            - name: MOAIC_JWT_SECRET
              valueFrom:
                secretKeyRef:
                  name: moaic-jwt-secret
                  key: MOAIC_JWT_SECRET
                  optional: true
          readinessProbe:
            httpGet:
              path: /health
              port: 8090
            initialDelaySeconds: 5
            periodSeconds: 10
          resources:
            requests:
              cpu: 100m
              # The adapter is a small streaming proxy (RSS ~30-50 Mi) but
              # also hosts the web download worker (yt-dlp + ffmpeg bursts);
              # 256 Mi request / 2 Gi limit keep the pod schedulable while
              # leaving download headroom (single replica, no-surge).
              memory: 256Mi
            limits:
              memory: 2Gi
          volumeMounts:
            {{- if and .Values.dataPvc .Values.dataPvc.enabled }}
            - name: data
              mountPath: /data
            {{- end }}
            # li7 (injected by inject.rs): the scan publishes into
            # /data/knowledge; the audio files stream from /media.
            - name: host-data
              mountPath: /data
            - name: media
              mountPath: /media
            # The host's user bin (yt-dlp, self-updating via tools/aria-dl):
            # read-only into the container so the web download worker can
            # exec it without baking it into the image.
            - name: yt-bin
              mountPath: /opt/ytbin
              readOnly: true
"#;

/// The brain container's dataPvc-conditional /data mount — the render's ONLY
/// brain mount. Replaced by an always-on block (hostPath /data + /vector)
/// followed by the aria-ask sidecar. One replacement, one template
/// generation.
const BRAIN_MOUNTS_OLD: &str = r"          {{- if and .Values.dataPvc .Values.dataPvc.enabled }}
          volumeMounts:
            - name: data
              mountPath: /data
          {{- end }}
";

const BRAIN_MOUNTS_PRELUDE: &str = r"          volumeMounts:
            {{- if and .Values.dataPvc .Values.dataPvc.enabled }}
            - name: data
              mountPath: /data
            {{- end }}
            # li7 (injected by inject.rs): the knowledge base (the
            # adapter publishes /data/knowledge/media; the brain ingests it)
            # + the embedded LanceDB — both on host directories.
            - name: host-data
              mountPath: /data
            - name: host-vector
              mountPath: /vector
            # li7 (injected by inject.rs): the media tree, READ-ONLY — the
            # offline surface (/api/offline/catalog + file) walks and serves
            # it to devices (app.offline, media_root: /media).
            - name: media
              mountPath: /media
              readOnly: true
";

const STARTUP_PROBE_OLD: &str = "          readinessProbe:
            httpGet:
              path: /readyz
              port: {{ .Values.containerPort }}
          livenessProbe:";

const STARTUP_PROBE_NEW: &str = "          # Cold-boot grace (injected by inject.rs): with a fresh
          # index the brain embeds thousands of chunks for minutes; the
          # 30 s readiness budget alone would flap and helm --wait would
          # time out the rollout (observed 2026-11-04).
          startupProbe:
            httpGet:
              path: /readyz
              port: {{ .Values.containerPort }}
            periodSeconds: 10
            failureThreshold: 60
          readinessProbe:
            httpGet:
              path: /readyz
              port: {{ .Values.containerPort }}
          livenessProbe:";

const VOLUMES_OLD: &str = r#"      {{- if and .Values.dataPvc .Values.dataPvc.enabled }}
      volumes:
        - name: data
          persistentVolumeClaim:
            claimName: {{ include "aria.fullname" . }}-data
      {{- end }}"#;

const VOLUMES_NEW: &str = r#"      volumes:
        {{- if and .Values.dataPvc .Values.dataPvc.enabled }}
        - name: data
          persistentVolumeClaim:
            claimName: {{ include "aria.fullname" . }}-data
        {{- end }}
        # li7 (injected): the audio files — a hostPath on the li7 host
        # (the music/audiobook/sermon collections live there, mounted at
        # /media in the pod; the adapter streams + scans them).
        # DirectoryOrCreate: an empty /media just means an empty catalog.
        - name: media
          hostPath:
            path: /home/ee/audio
            type: DirectoryOrCreate
        # li7 (injected): the knowledge base (the scan's media.jsonl.gz,
        # the sermon scripts) + the embedded LanceDB. Plain Directory: a
        # mis-typed path must fail loudly, not mount an empty dir.
        - name: host-data
          hostPath:
            path: /var/lib/aria-data
            type: Directory
        - name: host-vector
          hostPath:
            path: /var/lib/aria-lancedb
            type: Directory
        # li7 (injected): the user's per-user bin — holds the self-updating
        # yt-dlp (tools/aria-dl installs it to ~/.local/bin). Directory (not
        # Create): a missing dir is a misconfiguration, fail loudly.
        - name: yt-bin
          hostPath:
            path: /home/ee/.local/bin
            type: Directory"#;

const SVC_PORTS_NEW: &str = r"  ports:
    - name: api
      port: {{ .Values.containerPort }}
      targetPort: {{ .Values.containerPort }}
      protocol: TCP
    # li7: the aria-ask sidecar (the ASK surface).
    - name: ask
      port: 8090
      targetPort: 8090
      protocol: TCP
";

/// The rendered values.yaml declares the rollout strategy at its
/// deployment-level defaults (zero-downtime surge 1 / unavailable 0). On
/// li7 the node is memory-tight (bible ~51 Gi + pages ~8 Gi + co-tenants ≈
/// 61 Gi of 61.5 Gi allocatable), so an old aria pod and its replacement
/// may never both be scheduled — override to NO SURGE (0 / 1) here instead
/// of touching the chart template (a template mutation after `helm upgrade`
/// spawns a second ReplicaSet; values are part of the one upgrade).
const VALUES_STRATEGY_OLD: &str = "strategy:
  maxSurge: 1
  maxUnavailable: 0
";

const VALUES_STRATEGY_NEW: &str = "strategy:
  # li7 (injected by inject.rs): NO SURGE — see the constant's doc.
  maxSurge: 0
  maxUnavailable: 1
";

const INGRESS_OLD: &str = r#"        paths:
          - path: /
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: {{ $root.Values.containerPort }}
"#;

const INGRESS_NEW: &str = r#"        paths:
          # li7 (injected by inject.rs): the aria-ask sidecar owns the Alexa
          # endpoints + the /dl download-manager API; the BRAIN owns / and
          # serves the static web app (tessera `hydration: vanilla`, the
          # repo's web/ dir embedded in the image) — one origin, split here.
          - path: /alexa
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: 8090
          - path: /stream
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: 8090
          - path: /art
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: 8090
          # The Alexa skill icons (served by the adapter, baked in).
          - path: /skill-icons
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: 8090
          # The download manager's REST API (the SPA calls it same-origin).
          - path: /dl
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: 8090
          # Everything else — the SPA at /, /api, /mcp, /openapi.json,
          # /readyz — is the brain.
          - path: /
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: {{ $root.Values.containerPort }}
 "#;

/// Replace the first occurrence of `old` with `new` (the python injector
/// used str.replace(..., 1) semantics).
fn replace_once(text: &mut String, old: &str, new: &str) -> bool {
    if let Some(pos) = text.find(old) {
        let end = pos + old.len();
        text.replace_range(pos..end, new);
        true
    } else {
        false
    }
}

/// The service template's `  ports:` block: the anchor line plus every
/// following line that starts with whitespace (the block's body). Returns
/// the span end (exclusive offset just past the block).
fn service_ports_span(text: &str) -> Option<(usize, usize)> {
    let start = text.find("\n  ports:\n")? + 1;
    let mut end = start + "  ports:\n".len();
    while let Some(rest) = text.get(end..) {
        if rest.starts_with(' ') || rest.starts_with('\t') {
            let nl = rest.find('\n')?;
            end += nl + 1;
        } else {
            break;
        }
    }
    Some((start, end))
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: inject <helm-dir> [image-tag]   (tag default: latest)");
        exit(1);
    }
    let helm_dir = Path::new(&args[1]);
    let tag = args.get(2).cloned().unwrap_or_else(|| "latest".to_string());
    let sidecar = SIDECAR.replace("__TAG__", &tag);

    let dep = helm_dir.join("templates").join("deployment.yaml");
    let mut text = fs::read_to_string(&dep).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot read {dep:?}: {e}");
        exit(1);
    });
    // Idempotency markers are checked against the ORIGINAL file: the
    // sidecar insertion itself introduces "name: media" (a mount), which
    // would otherwise mask the volumes step on a fresh chart.
    let original = text.clone();

    // Re-injecting a chart that ALREADY carries the sidecar must still
    // refresh its image tag — the insertion block below is skipped when
    // "aria-ask" is present, which would otherwise leave the old tag in
    // place (the deploy then ships the previous adapter build).
    {
        const PREFIX: &str = "mosaic/aria-ask:";
        if let Some(i) = text.find(PREFIX) {
            let start = i + PREFIX.len();
            let rest = &text[start..];
            let end = rest
                .find(|c: char| !c.is_ascii_alphanumeric() && c != '-')
                .unwrap_or(0);
            let old = rest[..end].to_string();
            if old != tag {
                text.replace_range(start..start + end, &tag);
                println!("refreshed the aria-ask sidecar tag {old} -> {tag} in {dep:?}");
            }
        }
    }

    if !original.contains("aria-ask") {
        if !replace_once(&mut text, BRAIN_MOUNTS_OLD, &format!("{BRAIN_MOUNTS_PRELUDE}{sidecar}")) {
            eprintln!("ERROR: brain volumeMounts anchor not found in {dep:?} (chart changed? re-check the injection point)");
            exit(1);
        }
        println!("injected the aria-ask sidecar ({tag}) + the li7 hostPath mounts into {dep:?}");
    }

    if !original.contains("name: media") {
        if !replace_once(&mut text, VOLUMES_OLD, VOLUMES_NEW) {
            eprintln!("ERROR: volumes anchor not found in {dep:?} (chart changed?)");
            exit(1);
        }
        println!("injected the media hostPath volume into {dep:?}");
    }

    if !original.contains("startupProbe") {
        if replace_once(&mut text, STARTUP_PROBE_OLD, STARTUP_PROBE_NEW) {
            println!("injected the brain startupProbe (cold-boot grace) into {dep:?}");
        } else {
            println!("NOTE: startupProbe anchor not found in {dep:?} (chart changed?)");
        }
    }

    let svc = helm_dir.join("templates").join("service.yaml");
    let mut stext = fs::read_to_string(&svc).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot read {svc:?}: {e}");
        exit(1);
    });
    if !stext.contains("name: ask") {
        match service_ports_span(&stext) {
            Some((s, e)) => {
                stext.replace_range(s..e, SVC_PORTS_NEW);
                println!("normalized service ports in {svc:?}");
            }
            None => {
                eprintln!("ERROR: no ports block in {svc:?} (chart changed?)");
                exit(1);
            }
        }
    }

    let values = helm_dir.join("values.yaml");
    let mut vtext = fs::read_to_string(&values).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot read {values:?}: {e}");
        exit(1);
    });
    if !vtext.contains("maxSurge: 0") {
        if replace_once(&mut vtext, VALUES_STRATEGY_OLD, VALUES_STRATEGY_NEW) {
            println!("normalized the rollout strategy (no surge) in {values:?}");
        } else {
            println!("NOTE: strategy values anchor not found in {values:?} (chart changed?)");
        }
    }
    fs::write(&values, &vtext).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot write {values:?}: {e}");
        exit(1);
    });

    // Write the deployment back (the sidecar + volumes + strategy +
    // steps all operated on the in-memory copy).
    fs::write(&dep, &text).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot write {dep:?}: {e}");
        exit(1);
    });
    fs::write(&svc, &stext).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot write {svc:?}: {e}");
        exit(1);
    });

    let ing = helm_dir.join("templates").join("ingress.yaml");
    let mut itext = fs::read_to_string(&ing).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot read {ing:?}: {e}");
        exit(1);
    });
    if !itext.contains("/alexa") {
        if replace_once(&mut itext, INGRESS_OLD, INGRESS_NEW) {
            println!("injected the ingress path split into {ing:?}");
        } else {
            println!("NOTE: ingress path anchor not found in {ing:?} (already split or chart changed?)");
        }
    }
    fs::write(&ing, &itext).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot write {ing:?}: {e}");
        exit(1);
    });
}
